div.script:
document.addEventListener('DOMContentLoaded', function() {
    let labels = [];
    labels.push("");

    let url = '/feeds/posts/default?alt=json&max-results=3';
    if(labels.length > 0) {
        url = '/feeds/posts/default/-/' + encodeURIComponent(labels[0]) + '?alt=json&max-results=4';
    }

    fetch(url)
    .then(r => r.json())
    .then(d => {
        let entries = d.feed.entry || [];
        // Filter out current post
        let filtered = entries.filter(e => {
            let lnk = e.link.find(l => l.rel === 'alternate');
            return lnk && lnk.href !== "";
        }).slice(0, 3);

        if(filtered.length === 0) {
            document.getElementById('related-posts-container').style.display = 'none';
            return;
        }

        let html = '';
        filtered.forEach(p => {
            let title = p.title.$t;
            let link = p.link.find(l => l.rel === 'alternate').href;
            let img = p.media$thumbnail ? p.media$thumbnail.url.replace('s72-c', 'w400-h250-c') : 'https://placehold.co/400x250/f3f4f6/1f1f35?text=Read';
            html += `
                <a href="${link}" class="group block bg-white dark:bg-slate-800 border border-gray-100 dark:border-slate-700 rounded-2xl overflow-hidden hover:shadow-lg transition-all hover:border-brand-primary/30 flex flex-col">
                    <div class="h-32 w-full overflow-hidden shrink-0">
                        <img src="${img}" class="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700"/>
                    </div>
                    <div class="p-4 flex flex-col flex-1">
                        <h4 class="font-bold text-sm text-brand-dark dark:text-white line-clamp-2 leading-snug group-hover:text-brand-primary transition-colors">${title}</h4>
                        <div class="mt-auto pt-3 flex items-center justify-between text-xs font-bold text-gray-400">
                           <span class="text-brand-primary flex items-center gap-1">Read <i data-lucide="arrow-right" class="w-3 h-3"></i></span>
                        </div>
                    </div>
                </a>
            `;
        });
        document.getElementById('related-posts-grid').innerHTML = html;
        if(typeof lucide !== 'undefined') lucide.createIcons();
    })
    .catch(e => console.error(e));
});

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;
// 
      var cursor = null;
      if (items && items.length > 0) { cursor = parseInt(items[items.length - 1].timestamp) + 1; }
      var bodyFromEntry = function(entry) { var text = (entry && ((entry.content && entry.content.$t) || (entry.summary && entry.summary.$t))) || ''; if (entry && entry.gd$extendedProperty) { for (var k in entry.gd$extendedProperty) { if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') { return '<span class="deleted-comment">' + text + '</span>'; } } } return text; }
      var parse = function(data) { cursor = null; var comments = []; if (data && data.feed && data.feed.entry) { for (var i = 0, entry; entry = data.feed.entry[i]; i++) { var comment = {}; var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t); comment.id = id ? id[2] : null; comment.body = bodyFromEntry(entry); comment.timestamp = Date.parse(entry.published.$t) + ''; if (entry.author && entry.author.constructor === Array) { var auth = entry.author[0]; if (auth) { comment.author = { name: (auth.name ? auth.name.$t : undefined), profileUrl: (auth.uri ? auth.uri.$t : undefined), avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined) }; } } if (entry.link) { if (entry.link[2]) { comment.link = comment.permalink = entry.link[2].href; } if (entry.link[3]) { var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href); if (pid && pid[1]) { comment.parentId = pid[1]; } } } comment.deleteclass = 'item-control blog-admin'; if (entry.gd$extendedProperty) { for (var k in entry.gd$extendedProperty) { if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') { comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value; } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') { comment.displayTime = entry.gd$extendedProperty[k].value; } } } comments.push(comment); } } return comments; };
      var paginator = function(callback) { if (hasMore()) { var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50'; if (cursor) { url += '&published-min=' + new Date(cursor).toISOString(); } window.bloggercomments = function(data) { var parsed = parse(data); cursor = parsed.length < 50 ? null : parseInt(parsed[parsed.length - 1].timestamp) + 1; callback(parsed); window.bloggercomments = null; }; url += '&callback=bloggercomments'; var script = document.createElement('script'); script.type = 'text/javascript'; script.src = url; document.getElementsByTagName('head')[0].appendChild(script); } };
      var hasMore = function() { return !!cursor; };
      var getMeta = function(key, comment) { if ('iswriter' == key) { return (!!comment.author && comment.author.name == config.authorName && comment.author.profileUrl == config.authorUrl) ? 'true' : ''; } else if ('deletelink' == key) { return config.baseUri + '/comment/delete/' + config.blogId + '/' + comment.id; } else if ('deleteclass' == key) { return comment.deleteclass; } return ''; };
      var replybox = null; var replyUrlParts = null; var replyParent = undefined;
      var onReply = function(commentId, domId) { if (replybox == null) { replybox = document.getElementById('comment-editor'); if (replybox != null) { replybox.height = '250px'; replybox.style.display = 'block'; replyUrlParts = replybox.src.split('#'); } } if (replybox && (commentId !== replyParent)) { replybox.src = ''; document.getElementById(domId).insertBefore(replybox, null); replybox.src = replyUrlParts[0] + (commentId ? '&parentID=' + commentId : '') + '#' + replyUrlParts[1]; replyParent = commentId; } };
      var hash = (window.location.hash || '#').substring(1); var startThread, targetComment;
      if (/^comment-form_/.test(hash)) { startThread = hash.substring('comment-form_'.length); } else if (/^c[0-9]+$/.test(hash)) { targetComment = hash.substring(1); }
      var configJso = { 'maxDepth': config.maxThreadDepth };
      var provider = { 'id': config.postId, 'data': items, 'loadNext': paginator, 'hasMore': hasMore, 'getMeta': getMeta, 'onReply': onReply, 'rendered': true, 'initComment': targetComment, 'initReplyThread': startThread, 'config': configJso, 'messages': msgs };
      var render = function() { if (window.goog && window.goog.comments) { var holder = document.getElementById('comment-holder'); window.goog.comments.render(holder, provider); } };
      if (window.goog && window.goog.comments) { render(); } else { window.goog = window.goog || {}; window.goog.comments = window.goog.comments || {}; window.goog.comments.loadQueue = window.goog.comments.loadQueue || []; window.goog.comments.loadQueue.push(render); }
    })();
//

aside.script:
document.addEventListener('DOMContentLoaded', function() {
    fetch('/feeds/posts/default?alt=json&max-results=3')
    .then(r => r.json())
    .then(d => {
        let entries = d.feed.entry || [];
        let html = '';
        entries.forEach(p => {
            let title = p.title.$t;
            let link = p.link.find(l => l.rel === 'alternate').href;
            let img = p.media$thumbnail ? p.media$thumbnail.url.replace('s72-c', 'w150-h150-c') : 'https://placehold.co/150/f3f4f6/1f1f35?text=News';
            html += `
                <a href="${link}" class="group flex gap-3 items-center">
                    <div class="w-16 h-16 rounded-xl overflow-hidden shrink-0 bg-gray-100 border border-gray-100 dark:border-slate-700">
