body.script:
//
window.addEventListener('load', function() {
    if(window.lucide) { lucide.createIcons(); }
    loadTopBarTicker();
    loadBreakingTicker();
});
function toggleMobileMenu() {
    var menu = document.getElementById('mobileMenu');
    menu.classList.toggle('hidden');
}
// Top Bar Ticker — Latest 5 posts with Read More links
function loadTopBarTicker() {
    var el = document.getElementById('topBarTicker');
    if(!el) return;
    fetch('/feeds/posts/default?alt=json&max-results=5')
    .then(function(r){ return r.json(); })
    .then(function(data){
        if(!data.feed || !data.feed.entry) return;
        var items = data.feed.entry.map(function(e){
            var title = e.title.$t;
            var link = '';
            for(var i=0;i<e.link.length;i++){if(e.link[i].rel=='alternate'){link=e.link[i].href;break;}}
            return '📰 <a href="'+link+'" class="ticker-title">' + title + '</a> — <a href="'+link+'" class="ticker-readmore">Read More →</a>';
        });
        el.innerHTML = items.join('  |  ');
    })
    .catch(function(){
        el.textContent = 'Verify Before You Believe — Fact Check, Fake News Alert, Government Scheme Verification, Job Alert Verification & Online Scam Detection.';
    });
}
// Breaking Ticker — Category-specific posts (Fact Check, Fake News, Scam Alert)
function loadBreakingTicker() {
    var el = document.getElementById('breakingTicker');
    if(!el) return;
    var labels = ['Fact Check','Fake News','Scam Alert','Govt Schemes'];
    var labelIcons = {'Fact Check':'🔍','Fake News':'⚠️','Scam Alert':'🛡️','Govt Schemes':'🏛️'};
    var promises = labels.map(function(label){
        return fetch('/feeds/posts/default/-/'+encodeURIComponent(label)+'?alt=json&max-results=2')
        .then(function(r){ return r.json(); })
        .then(function(data){
            if(!data.feed || !data.feed.entry) return [];
            return data.feed.entry.map(function(e){
                var title = e.title.$t;
                var link = '';
                for(var i=0;i<e.link.length;i++){if(e.link[i].rel=='alternate'){link=e.link[i].href;break;}}
                var icon = labelIcons[label] || '📰';
                return icon + ' <a href="'+link+'" class="ticker-title">' + title + '</a> — <a href="'+link+'" class="ticker-readmore">Read More →</a>';
            });
        })
        .catch(function(){ return []; });
    });
    Promise.all(promises).then(function(results){
        var all = [];
        results.forEach(function(arr){ all = all.concat(arr); });
        if(all.length > 0) {
            el.innerHTML = all.join('  |  ');
        } else {
            el.textContent = '🔴 Latest fact checks and breaking news — stay tuned for updates!';
        }
    });
}

// Theme Toggle Listener
var themeToggleBtn = document.getElementById('themeToggle');
if(themeToggleBtn) {
    themeToggleBtn.addEventListener('click', function() {
        document.documentElement.classList.toggle('dark');
        if(document.documentElement.classList.contains('dark')) {
            localStorage.setItem('theme', 'dark');
        } else {
            localStorage.setItem('theme', 'light');
        }
    });
}
//
